{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Perindopril, an ester prodrug with the highest transfer score, gave 19% oral bioavailability of its active moiety in young healthy subjects, just below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Cyclandelate, a cyclohexyl-containing ester, showed extremely low oral bioavailability in humans, supporting low F for the query's ester/cyclohexyl features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Oxybutynin, a lipophilic ester with moderate-high transfer, had absolute oral bioavailability of 6.2% in healthy volunteers, well below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Withaferin A, a steroidal natural product, showed poor oral bioavailability in humans, directly relevant to the query's steroid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "AKBA, a steroid-like triterpene, had poor oral bioavailability due to low absorption/extensive metabolism, analogous to the query's lipophilic steroid ester.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "17β-Estradiol, a steroid, had absolute oral bioavailability of about 5% in humans, below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Paclitaxel, a lipophilic ester natural product, had oral bioavailability of 13% without P-gp/CYP3A inhibition, below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Ipratropium bromide had oral systemic availability around 2%, below 20%, though its quaternary ammonium polarity limits direct structural transfer.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "β-Sitosterol, a steroid, had absolute oral bioavailability of 0.41%, below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Drospirenone, a steroidal progestin, has high oral bioavailability (76–85%) in humans, showing that not all steroids are poorly bioavailable; however, it lacks the ester/acetal prodrug and enone features of the query and is a less transferable counterexample.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a lipophilic corticosteroid ester/acetal prodrug. Multiple high-transfer analogues with ester, steroid, or prodrug features show absolute oral bioavailability well below 20% (oxybutynin 6%, estradiol 5%, paclitaxel 13%, β-sitosterol 0.4%). The few high-F steroid/outlier records are less transferable or condition-specific. Therefore, F < 20% is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for ciclesonide itself in the provided evidence; prediction relies on transferable analogues.",
    "Most analogues are not corticosteroids with the same 16,17-acetal/21-ester prodrug motif; first-pass ester hydrolysis and CYP3A/P-gp contributions are inferred.",
    "Perindopril in cirrhosis reached 30% and one ipratropium record reported ~32%, but these are condition-specific or outlier values that do not outweigh the consistent low-F evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

